import { strToU8, zipSync } from 'fflate';

export interface SheetFixture {
	name: string;
	/** Used range the sheet records, e.g. `A1:C12`. Omitted for a sheet that records none. */
	range?: string;
	hidden?: boolean;
}

/**
 * Builds a real .xlsx — a zip of the parts an outline is read from — so the tests exercise the
 * archive and XML handling rather than a stub. No cells are written: nothing reads them.
 */
export const buildWorkbook = (sheets: SheetFixture[]): Buffer => {
	const parts: Record<string, Uint8Array> = {
		'[Content_Types].xml': strToU8(contentTypes(sheets.length)),
		'xl/workbook.xml': strToU8(workbook(sheets)),
		'xl/_rels/workbook.xml.rels': strToU8(workbookRels(sheets.length)),
	};

	sheets.forEach((sheet, index) => {
		parts[sheetPath(index)] = strToU8(worksheet(sheet.range));
	});

	return Buffer.from(zipSync(parts));
};

const sheetPath = (index: number): string => `xl/worksheets/sheet${index + 1}.xml`;

const workbook = (sheets: SheetFixture[]): string => {
	const entries = sheets.map((sheet, index) => {
		const state = sheet.hidden ? ' state="hidden"' : '';
		return `<sheet name="${escapeXml(sheet.name)}" sheetId="${index + 1}"${state} r:id="rId${index + 1}"/>`;
	});

	return `<?xml version="1.0" encoding="UTF-8"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${entries.join('')}</sheets></workbook>`;
};

const workbookRels = (sheetCount: number): string => {
	const entries = Array.from({ length: sheetCount }, (_, index) => {
		return `<Relationship Id="rId${index + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`;
	});

	return `<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${entries.join('')}</Relationships>`;
};

const worksheet = (range: string | undefined): string => {
	const dimension = range ? `<dimension ref="${range}"/>` : '';
	return `<?xml version="1.0" encoding="UTF-8"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">${dimension}<sheetData/></worksheet>`;
};

const contentTypes = (sheetCount: number): string => {
	const overrides = Array.from({ length: sheetCount }, (_, index) => {
		return `<Override PartName="/${sheetPath(index)}" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`;
	});

	return `<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>${overrides.join('')}</Types>`;
};

const escapeXml = (value: string): string => {
	return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};

import { zipSync } from 'fflate';
import { describe, expect, it } from 'vitest';

import { describeWorkbook } from '../src/services/workbook';
import { buildWorkbook } from './helpers/xlsx-fixture';

describe('describeWorkbook', () => {
	it('lists every sheet in tab order, so nothing after the first one is invisible', () => {
		const outline = describeWorkbook(
			buildWorkbook([
				{ name: 'Cover', range: 'A1:B8' },
				{ name: 'FY26', range: 'A1:N412' },
				{ name: 'Archive', range: 'A1:N900' },
			]),
		);

		expect(outline).toContain('Excel workbook with 3 sheets');
		expect(outline).toContain("1. 'Cover' — 8 rows × 2 columns (A1:B8)");
		expect(outline).toContain("2. 'FY26' — 412 rows × 14 columns (A1:N412)");
		expect(outline).toContain("3. 'Archive' — 900 rows × 14 columns (A1:N900)");
	});

	it('shows how to query a sheet, naming one that really exists', () => {
		const outline = describeWorkbook(buildWorkbook([{ name: 'Budget FY26', range: 'A1:C3' }]));

		expect(outline).toContain('Excel workbook with 1 sheet');
		expect(outline).toContain("read_xlsx('<path>', sheet = 'Budget FY26')");
	});

	it('flags a hidden sheet rather than passing it off as the working copy', () => {
		const outline = describeWorkbook(
			buildWorkbook([
				{ name: 'Summary', range: 'A1:C3' },
				{ name: 'Old', range: 'A1:C3', hidden: true },
			]),
		);

		expect(outline).toContain("1. 'Summary' —");
		expect(outline).toContain("2. 'Old' (hidden) —");
	});

	it('gives back the sheet name as Excel shows it, not as the XML escapes it', () => {
		const outline = describeWorkbook(buildWorkbook([{ name: 'Q1 & Q2 <draft>', range: 'A1:A1' }]));

		expect(outline).toContain("'Q1 & Q2 <draft>'");
	});

	it('counts columns past the first alphabet', () => {
		const outline = describeWorkbook(buildWorkbook([{ name: 'Wide', range: 'A1:AB2' }]));

		expect(outline).toContain('2 rows × 28 columns');
	});

	it('reads a single-cell range as one cell instead of failing', () => {
		const outline = describeWorkbook(buildWorkbook([{ name: 'Empty', range: 'A1' }]));

		expect(outline).toContain("'Empty' — 1 row × 1 column (A1)");
	});

	it('says so when a sheet records no used range, rather than inventing a size', () => {
		const outline = describeWorkbook(buildWorkbook([{ name: 'Notes' }]));

		expect(outline).toContain("'Notes' — size not recorded in the file");
	});

	it('warns that the counts cover the used range, not the table inside it', () => {
		const outline = describeWorkbook(buildWorkbook([{ name: 'FY26', range: 'A1:C9' }]));

		expect(outline).toMatch(/used range the file records/);
	});

	it('reports a file that is not an archive as unreadable instead of guessing', () => {
		expect(() => describeWorkbook(Buffer.from('PK\u0003\u0004 not really a zip'))).toThrow(
			/corrupt or password-protected/,
		);
	});

	it('reports an archive that holds no workbook part', () => {
		const notAWorkbook = Buffer.from(zipSync({ 'hello.txt': new Uint8Array([1, 2, 3]) }));

		expect(() => describeWorkbook(notAWorkbook)).toThrow(/no xl\/workbook\.xml part/);
	});

	it('reports a workbook with no sheet at all', () => {
		expect(() => describeWorkbook(buildWorkbook([]))).toThrow(/declares no sheet/);
	});
});

